dir:






























  &DefaultButton;




function dir$dmloaicong(p){
  this.constructor(p);
}
dir$dmloaicong.prototype = new DirEvent();
dir$dmloaicong.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmloaicong.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmloaicongDisabledMasterField(p, g);

}

function dir$dmloaicongDisabledMasterField(p, g){

  if(p.valForm('ma_loai').trim() != '')
  {
    p.setDisabled('ma_loai', true);
  }
  else
  {
    p.setDisabled('ma_loai', false);
  }
}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã loại container đã tồn tại' else N'Container Type Code is exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã loại container đã tồn tại' else N'Container Type Code is exists' end
